INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (315804, 13962, 'France 24', 'en', 'Live: Russian attack sets ablaze Ukraine’s Izmail port infrastructure', 'https://www.france24.com/en/europe/20260813-live-russian-attack-sets-ablaze-ukraine-s-izmail-port-infrastructure', 'Russia struck the area ​around Ukraine''s largest Danube port of Izmail overnight, causing damage ​and setting ‌off a fire, ⁠regional authorities said Thursday. Meanwhile Moscow said it downed 362 Ukrainian drones overnight as an attack in Russia''s Salavat area triggered a blaze at an oil refinery, according to local authorities. Follow our liveblog for the latest updates.', 'https://s.france24.com/media/display/141041a2-96dc-11f1-b630-005056a90284/w:1024/p:16x9/2026-08-12T105629Z-1787001111-RC2YWMATSI3R-RTRMADP-3-UKRAINE-CRISIS-ATTACK-NOVOROSSIYSK.jpg', '2026-08-13T06:14:52+00:00', '2026-08-13T06:19:28.931909'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
