INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (316344, 13988, 'The Times of India', 'en', '99% of California''s sunflower sea stars vanished; a colony may offer hope', 'https://timesofindia.indiatimes.com/science/more-than-99-of-californias-sunflower-sea-stars-vanished-now-scientists-have-found-a-mysterious-colony-that-could-help-revive-dying-kelp-forests/articleshow/133200597.cms', 'Ten years ago, sunflower sea stars faced near extinction due to a devastating marine epidemic, leading to unchecked sea urchin populations that destroyed essential kelp forests. Recently, a newly identified colony of these sea stars has rekindled hope for ecological restoration. Researchers are examining their resilience to diseases, which could greatly benefit efforts to reintroduce these vital predators to their ocean habitats.', 'https://static.toiimg.com/photo/msid-133200760,imgsize-137685.cms', '2026-08-13T06:32:15+00:00', '2026-08-13T07:07:02.200996'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
