INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (313477, 14012, 'Aaj Tak', 'hi', 'Donald Trump के दावों पर Iran का बड़ा पलटवार!', 'https://www.aajtak.in/short-videos/video/iran-rejects-trump-hormuz-control-claim-says-strait-remains-closed-until-tehran-demands-are-accepted-by-america-mmta-2621016-2026-08-13', 'ईरान ने डोनाल्ड ट्रंप के होर्मुज जलडमरूमध्य पर अमेरिकी नियंत्रण के दावे को खारिज कर दिया है. तेहरान का कहना है कि जलमार्ग अभी भी बंद है और अमेरिका की ओर से युद्ध व नाकाबंदी खत्म करने समेत उसकी शर्तें माने जाने तक इसे नहीं खोला जाएगा. ईरानी अधिकारियों ने जब्त संपत्तियां लौटाने और क्षेत्र में संघर्षविराम की मांग भी दोहराई है. होर्मुज पर तनाव से तेल और जहाजरानी बाजार दबाव में हैं.', '', '2026-08-13T03:26:41+00:00', '2026-08-13T03:34:40.803606'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (313478, 14012, 'Aaj Tak', 'hi', 'मिसाइलें खत्म हुईं तो और खतरनाक होगा Iran, IRGC ने दी चेतावनी!', 'https://www.aajtak.in/short-videos/video/iran-signals-prolonged-war-with-america-until-trump-term-ends-warns-of-rising-threats-and-retaliation-mmta-2621008-2026-08-13', 'ईरान और अमेरिका के बीच जारी युद्ध को लेकर ईरानी रिवोल्यूशनरी गार्ड्स के वरिष्ठ सलाहकार मोहम्मद रजा नकदी ने लंबा संघर्ष जारी रखने का संकेत दिया है. उन्होंने कहा कि युद्ध को ट्रंप के मौजूदा कार्यकाल तक खींचने से अमेरिका पर दबाव बढ़ाया जा सकता है. नकदी ने दावा किया कि ईरान लगातार मिसाइल बना रहा है और भविष्य में हमला करने वाले किसी भी देश को इसकी बड़ी कीमत चुकानी पड़ सकती है.', '', '2026-08-13T02:53:22+00:00', '2026-08-13T03:34:40.815569'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
